cases:[['🤒',['„Sunt fierbinte și obosit.”','“I feel hot and tired.”','„Forró vagyok és fáradt.”','«Я гарячий і втомлений.»'],'thermo'],['🦵',['„M-am zgâriat la genunchi. Rana e deja spălată.”','“I scraped my knee. It’s already been washed.”','„Lehorzsoltam a térdem. A sebet már kimostuk.”','«Я подряпав коліно. Ранку вже промили.»'],'plaster'],['💓',['„Doctorul vrea să-mi asculte inima.”','“The doctor wants to listen to my heart.”','„Az orvos meg akarja hallgatni a szívemet.”','«Лікар хоче послухати моє серце.»'],'stetho'],['🤕',['„M-am lovit la mână și s-a umflat puțin.”','“I bumped my arm and it’s a bit swollen.”','„Beütöttem a kezem, és kicsit megdagadt.”','«Я вдарив руку, і вона трохи набрякла.»'],'ice'],['👀',['„Nu văd bine literele de pe tablă.”','“I can’t see the letters on the board well.”','„Nem látom jól a betűket a táblán.”','«Я погано бачу літери на дошці.»'],'eyes'],['😬',['„Mă doare un dinte când mănânc.”','“A tooth hurts when I eat.”','„Fáj egy fogam, amikor eszem.”','«У мене болить зуб, коли я їм.»'],'dentist'],['🤧',['„Strănut întruna!”','“I keep sneezing!”','„Folyton tüsszögök!”','«Я весь час чхаю!»'],'tissue']],
