function pickGame(){const a=age(),kind=a<=5?'ripe':a<=8?'count':'weight';let tree=[],bag=[],done=false,target=0,want=null;
if(kind==='ripe'){const r=4+rand(4),g=3+rand(3);tree=mix([...Array(r).fill('apple'),...Array(g).fill('green')]);target=r}
else if(kind==='count'){want=pick(['apple','pear','peach','cherry']);target=3+rand(4);const others=['apple','pear','peach','cherry','grapes'].filter(f=>f!==want);tree=mix([...Array(target+2+rand(2)).fill(want),...Array.from({length:5+rand(3)},()=>pick(others))])}
else{tree=mix(Array.from({length:11},()=>pick(['apple','pear','peach','cherry','grapes'])));const sub=mix([...tree.keys()]).slice(0,3+rand(3));target=sub.reduce((s,i)=>s+FRUIT[tree[i]][1],0)}
stage.dataset.mode=kind;stage.dataset.target=target;if(want)stage.dataset.want=want;
help(kind==='ripe'?L(PK.young):kind==='count'?fmt(L(PK.mid),{n:target,icon:FRUIT[want][0],name:L(FRUIT[want][2])}):fmt(L(PK.old),{w:target}));
const orchard=E('div','','orchard');orchard.setAttribute('role','group');orchard.setAttribute('aria-label',L(PK.tree));const basketBox=E('div','','fruit-basket');basketBox.setAttribute('role','group');basketBox.setAttribute('aria-label',L(PK.basket));const info=E('p','','versus-pairs');
const sum=()=>bag.reduce((s,i)=>s+FRUIT[tree[i]][1],0);
const btns=tree.map((f,i)=>{const [ic,w,nm]=FRUIT[f];const b=B('',()=>take(i),'fruit');b.dataset.fruit=f;b.dataset.i=i;if(kind==='weight'){b.dataset.w=w;b.append(E('span',ic),E('small',`${w} g`))}else b.append(E('span',ic));b.setAttribute('aria-label',kind==='weight'?`${L(nm)}, ${w} g`:L(nm));orchard.append(b);return b});
const paint=()=>{info.textContent=kind==='weight'?fmt(L(PK.weight),{w:sum(),t:target}):fmt(L(PK.count),{n:bag.length});basketBox.replaceChildren(...bag.map(i=>{const [ic,w,nm]=FRUIT[tree[i]],b=B(ic,()=>back(i),'fruit in-basket');b.setAttribute('aria-label',fmt(L(PK.back),{f:L(nm)}));b.disabled=done||kind!=='weight';return b}));btns.forEach((b,i)=>{b.hidden=bag.includes(i);b.disabled=done})};
function finish(){done=true;paint();gardenCelebrate('craft-picking');say(L(PK.full));stage.append(nextBtn(render))}
function take(i){if(done||bag.includes(i))return;const f=tree[i];
if(kind==='ripe'&&f==='green'){gardenMiss('craft-picking');say(L(PK.unripe),false);return}
if(kind==='count'){if(f!==want){gardenMiss('craft-picking');say(fmt(L(PK.wrongFruit),{icon:FRUIT[want][0]}),false);return}if(bag.length>=target){say(L(PK.enough),false);return}}
bag.push(i);window.gardenSound?.('pop');status.textContent='';paint();
if(kind==='weight'){const s=sum();if(s>target){gardenMiss('craft-picking');say(L(PK.over),false)}else if(s===target)finish()}else if(bag.length===target)finish()}
function back(i){if(done)return;bag=bag.filter(x=>x!==i);status.textContent='';paint()}
stage.append(orchard,info,basketBox);paint()}
