let craft=null,act=null,stage,status,token=0;const rot={};
const say=(msg,good=true)=>{status.textContent=msg;status.classList.toggle('bad',!good)};
const listen=text=>B(u('listen'),()=>gardenSpeak(text,true),'speak-btn');
const help=text=>{stage.append(E('p',text,'studio-help'));if(age()<=6)stage.append(listen(text))};
const nextBtn=fn=>{const b=B(u('another'),fn,'primary craft-next');return b};
function numOptions(ans){const s=new Set([ans]);const step=ans>=200?50:ans>=40?10:1;let k=1;while(s.size<4&&k<30){[ans+k*step,ans-k*step].forEach(v=>{if(v>=0&&s.size<4)s.add(v)});k++}return mix([...s])}

// Pași în ordine
function orderGame(c){const a=age(),avail=c.seqs.filter(s=>a>=(s.minAge||0)&&a<=(s.max||99));const r=rot[craft+'o']=(rot[craft+'o']??rand(avail.length));const s=avail[r%avail.length];const steps=(a<=5&&s.young?s.young.map(i=>s.steps[i]):s.steps);let done=0;
help(u('orderHelp'));stage.append(E('h3',L(s.title),'craft-seq-title'));const scene=E('div','','craft-scene');scene.setAttribute('aria-hidden','true');const list=E('ol','','craft-done');const choices=E('div','','craft-choices');stage.append(scene,list,choices);
const draw=()=>{scene.replaceChildren();if(s.visual==='house')scene.append(houseSVG(steps.slice(0,done).map(x=>x[2])));else{const big=E('span',done?(steps[done-1][2]||steps[done-1][0]):'✨','craft-big');scene.append(big)}};
const btns=mix(steps.map((st,i)=>[st,i])).map(([st,i])=>{const b=B(`${st[0]} ${L(st[1])}`,()=>tap(i,b),'craft-choice');b.dataset.step=i;choices.append(b);return b});
function tap(i,b){if(done>=steps.length)return;if(i!==done){gardenMiss('craft-'+craft);say(u('orderWrong'),false);b.classList.remove('shake');b.getBoundingClientRect();b.classList.add('shake');return}done++;b.disabled=true;b.hidden=true;list.append(E('li',`${steps[i][0]} ${L(steps[i][1])}`));window.gardenSound?.('pop');status.textContent='';draw();if(done===steps.length){gardenCelebrate('craft-'+craft);say(u('orderDone'));stage.append(nextBtn(()=>{rot[craft+'o']++;render()}))}}
draw()}
function houseSVG(ids){const has=k=>ids.includes(k),svg=S('svg',{viewBox:'0 0 200 150',class:'house-svg'});svg.append(S('rect',{x:0,y:0,width:200,height:150,fill:has('plan')&&!has('found')?'#2f6fb0':'#bfe3ff'}));
if(has('plan')&&!has('found')){for(let x=10;x<200;x+=20)svg.append(S('line',{x1:x,y1:0,x2:x,y2:150,stroke:'#ffffff44'}));svg.append(S('rect',{x:55,y:60,width:90,height:70,fill:'none',stroke:'#fff','stroke-width':2,'stroke-dasharray':'5 4'}),S('polyline',{points:'50,62 100,28 150,62',fill:'none',stroke:'#fff','stroke-width':2,'stroke-dasharray':'5 4'}))}
svg.append(S('rect',{x:0,y:130,width:200,height:20,fill:'#7cb342'}));if(has('found'))svg.append(S('rect',{x:48,y:124,width:104,height:10,fill:'#9e9e9e',stroke:'#555'}));
if(has('walls')){svg.append(S('rect',{x:55,y:64,width:90,height:60,fill:has('paint')?'#ffd166':'#c8a27a',stroke:'#6d4c41','stroke-width':2}));if(!has('paint'))for(let y=72;y<124;y+=10)svg.append(S('line',{x1:55,y1:y,x2:145,y2:y,stroke:'#6d4c4155'}))}
if(has('windows'))svg.append(S('rect',{x:64,y:78,width:22,height:18,fill:'#90caf9',stroke:'#37474f','stroke-width':2}),S('rect',{x:114,y:78,width:22,height:18,fill:'#90caf9',stroke:'#37474f','stroke-width':2}),S('rect',{x:90,y:96,width:20,height:28,fill:'#8d6e63',stroke:'#37474f','stroke-width':2}));
if(has('roof'))svg.append(S('polygon',{points:'46,66 100,26 154,66',fill:'#e53935',stroke:'#7f1d1d','stroke-width':2}));if(has('paint'))svg.append(S('circle',{cx:30,cy:126,r:5,fill:'#f48fb1'}),S('circle',{cx:170,cy:126,r:5,fill:'#fdd835'}));return svg}

// Unealta potrivită
function toolGame(c){matchGame(c)}
function matchGame(c,spec){spec=spec||{cases:c.cases,pool:c.pool,dict:TOOLS,help:U.toolHelp};const rk=craft+act,r=rot[rk]=(rot[rk]??rand(spec.cases.length));const [icon,text,ansRaw]=spec.cases[r%spec.cases.length],answers=[].concat(ansRaw),ans=answers[0];let solved=false;
stage.append(E('p',L(spec.help),'studio-help'));const scene=E('div','','craft-problem');scene.append(E('span',icon,'craft-big'),E('p',L(text),'craft-say'));stage.append(scene);if(age()<=6)stage.append(listen(L(text)));
const opts=mix([ans,...mix(spec.pool.filter(k=>!answers.includes(k))).slice(0,age()<=5?2:3)]),row=E('div','',spec.dict===TOOLS?'craft-tools':'craft-tools craft-words');stage.dataset.answer=ans;
opts.forEach(k=>{const [ti,tl]=spec.dict[k],b=B('',()=>{if(solved)return;if(answers.includes(k)){solved=true;b.classList.add('right');gardenCelebrate('craft-'+(spec.game||craft));say(`${u('good')} ${ti} ${L(tl)}`.replace(/  +/g,' '));if(spec.speak)gardenSpeak(L(tl),true);stage.append(nextBtn(()=>{rot[rk]++;render()}))}else{gardenMiss('craft-'+(spec.game||craft));b.classList.add('wrong-pick');say(u(spec.dict===TOOLS?'toolWrong':'nearly'),false)}},'craft-tool');b.dataset.tool=k;if(ti)b.append(E('span',ti,'craft-tool-icon'));b.append(E('span',L(tl)));row.append(b)});stage.append(row)}

// Calcule pe vârstă
function mathGame(c){const q=c.math(age());let solved=false;const text=L(q.text);help(text);if(q.show){const v=E('div',q.show,'craft-show');v.setAttribute('aria-hidden','true');stage.append(v)}
const opts=q.options?mix(q.options):numOptions(q.answer),row=E('div','','craft-answers');stage.dataset.answer=q.answer;
opts.forEach(o=>{const b=B(String(o),()=>{if(solved)return;if(String(o)===String(q.answer)){solved=true;b.classList.add('right');gardenCelebrate('craft-math');say(u('good'));stage.append(nextBtn(render))}else{gardenMiss('craft-math');b.classList.add('wrong-pick');say(q.hint?`${u('nearly')} ${L(q.hint)}`:u('nearly'),false)}},'craft-answer');row.append(b)});stage.append(row)}

