if(!small){svg.append(S('ellipse',{cx:100,cy:178,rx:78,ry:10,fill:'#6d4c41'}),S('ellipse',{cx:100,cy:174,rx:70,ry:8,fill:'#8d6e63',class:'wheel-top'}))}
const cp=S('clipPath',{id});cp.append(S('path',{d}));svg.append(cp,S('path',{d,fill:col,stroke:'#3b2a20','stroke-width':2.5}));const g=S('g',{'clip-path':`url(#${id})`}),dark='#00000040',light='#ffffff99';
